INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (0, 'h1', 'Week 47', '2026-11-16', '2026-11-22', '2026-11-15', 'headline', '', '', 'Range mode. BTC, ETH and INJ trade in wide ranges (BTC 59,888 to 81,503, ETH 1,512 to 2,357, INJ 6.764 to 9.409) and all sit in the lower half after last week''s slide (BTC -12.5%, ETH -14%, INJ -13% since Monday). Trade the edges: longs on sweeps of the range lows, shorts on failed range highs and mid rejections, profits at the mid. Event risk: NVIDIA results Tuesday night, FOMC minutes Wednesday.', '', '', '', '', '', '');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (1, 'x1', 'Week 47', '2026-11-16', '2026-11-22', '2026-11-15', 'exit', 'BTC', 'BTC', 'Exit in force, 200 hold active', '', '', '', '', '', 'Bearish below every EMA (EMA50 77,568, EMA200 76,137; 10 closes below the 200). Longs are range trades only. Shorts are held until two closes back above the EMA200.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (2, 'x2', 'Week 47', '2026-11-16', '2026-11-22', '2026-11-15', 'exit', 'ETH', 'ETH', 'Exit in force, 200 hold active', '', '', '', '', '', 'Bearish below every EMA (EMA50 2,294, EMA200 2,293; 10 closes below the 200). Longs are range trades only. Shorts are held until two closes back above the EMA200.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (3, 'x3', 'Week 47', '2026-11-16', '2026-11-22', '2026-11-15', 'exit', 'SPX', 'ES (S&P)', 'Exit rule in force, choppy', '', '', '', '', '', 'Cash S&P 7 closes below the EMA50 (7,635) but above the EMA200 (7,367); it crossed the EMA21 8 times in 20 days, which is range behaviour. Weekly trend Below both.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (4, 'x4', 'Week 47', '2026-11-16', '2026-11-22', '2026-11-15', 'exit', 'NDX', 'NQ (est.)', 'Exit in force, 1 close below the EMA200', '', '', '', '', '', 'NAS100 27,943 closed under the EMA200 (28,127) on Friday; a second close under it on Monday restarts the 200 hold rule. EMA50 29,102.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (5, 'l1', 'Week 47', '2026-11-16', '2026-11-22', '2026-11-15', 'long', 'BTC', 'BTC', 'Range low sweep 59,888', 'Daily swing failure at 59,888 or a 4H sweep that closes back above it (both alerted)', '57,297 (your plan), under the July low 57,718 and the 300-week SMA about 57,770', '67,218 (your plan, about 2.6R from 60,078), then mid 71,032', 'Setup Only (Bearish, below EMA200)', '59888', 'Your long position on the weekly chart: entry 60,078, stop 57,297, target 67,218. BTC traded down to 62,094 today, 3.7% above the level.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (6, 'l2', 'Week 47', '2026-11-16', '2026-11-22', '2026-11-15', 'long', 'BTC', 'BTC', 'Mid reclaim 71,032', 'Daily close back above the mid 71,032 (alerted)', 'Below the reclaim day''s low', 'Range high 81,503', 'Setup Only', '71032.1', 'Turns the range trade to the upper half. The EMA21 (75,017), EMA200 (76,137) and EMA50 (77,568) sit on the way up.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (7, 'l3', 'Week 47', '2026-11-16', '2026-11-22', '2026-11-15', 'long', 'ETH', 'ETH', 'Range low sweep 1,512', 'Daily swing failure at 1,512 or a 4H sweep that closes back above it (alerted)', 'Below the sweep low; 1,385 is the next level', 'Quarter line 1,749, then mid 1,982', 'Setup Only (Bearish, below EMA200)', '1512.17', 'The range low is the January to August floor. Below it, 1,385.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (8, 'l4', 'Week 47', '2026-11-16', '2026-11-22', '2026-11-15', 'long', 'ETH', 'ETH', 'Quarter line 1,749 reclaim', 'ETH swept 1,749 today (low 1,714) and trades back above it. A daily close above 1,749 tonight (01:00) is a daily sweep and reclaim (alerted)', 'Below today''s low, about 1,700', 'Mid 1,982: about 2.5R from 1,780 with a stop at 1,700, only about 1.3R from today''s 1,825, so wait for a retest', 'Setup Only, smaller size', '1749.28', 'A dashed quarter line, not the range low: a weaker level than 1,512.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (9, 'l5', 'Week 47', '2026-11-16', '2026-11-22', '2026-11-15', 'long', 'INJ', 'INJ', 'Range low swing failure 6.764', 'Printed on 14 Nov (low 6.664, close 6.808) and swept again today (6.592). Enter on a 4H close back above 6.764 after a retest, or on the next sweep that closes back above', 'Below today''s low 6.592, about 6.55', 'Mid 8.176 (about 2.6R from 7.00), then range high 9.409', 'Setup Only, half size: INJ''s daily range is about 10% (BTC about 3%)', '6.764', 'INJ is above its 200-day average (about 5.81), unlike BTC and ETH. It broke the rising trendline of its triangle this week. Below 6.764: 6.068, then the yearly open zone about 3.7 to 4.2.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (10, 'l6', 'Week 47', '2026-11-16', '2026-11-22', '2026-11-15', 'long', 'SPX', 'ES (S&P)', 'Range low sweep 7,329', 'Daily sweep of 7,329.25 that closes back above', 'Below the sweep low', 'Mid 7,620', 'Setup Only (weekly Below both)', '7329.25', 'ES closed Friday at 7,583, between the mid and the range low. 7,045 is the next level below.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (11, 'l7', 'Week 47', '2026-11-16', '2026-11-22', '2026-11-15', 'long', 'NDX', 'NQ (est.)', 'Range low hold 27,220', 'Pullback that holds 27,220 on a daily close, or sweeps it and closes back above', 'Below the sweep low', 'EMA200 about 28,240, then mid 29,000', 'Setup Only (below the EMA200)', '27220', 'NQ won back 27,220 on 9 Nov and is about 28,040 (estimate). Check your NQ1! chart: the alerts see daily closes only.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (12, 's1', 'Week 47', '2026-11-16', '2026-11-22', '2026-11-15', 'short', '', '', 'Crypto: shorts only at failed range highs and mid rejections', '', '', '', '', '', 'Short a swing failure at the range high (BTC 81,503, ETH 2,357, INJ 9.409) or a rejection at the mid (BTC 71,032, ETH 1,982, INJ 8.176), stop above that candle''s high, target the range low. None is near now. BTC and ETH have the 200 hold rule active, which favours shorts on rallies into the mid.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (13, 's2', 'Week 47', '2026-11-16', '2026-11-22', '2026-11-15', 'short', '', '', 'ES rejected at mid on Friday: range short trigger', '', '', '', '', '', 'High 7,669, close 7,583 under the 7,620 mid after a close below it. Stop above 7,669, target the range low 7,329 (about 2.6R from 7,583 with a stop at 7,680). Judgment: index mid shorts are a small test sample, and NVIDIA on Tuesday can gap it either way.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (14, 'r1', 'Week 47', '2026-11-16', '2026-11-22', '2026-11-15', 'rule', '', '', 'Range mode until a new trend forms: trade the edges, take profits at the mid, nothing in the middle of the range.', '', '', '', '', '', '');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (15, 'r2', 'Week 47', '2026-11-16', '2026-11-22', '2026-11-15', 'rule', '', '', 'A touch is not a trigger: wait for the daily swing failure or the 4H close back inside. The alerts report both.', '', '', '', '', '', '');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (16, 'r3', 'Week 47', '2026-11-16', '2026-11-22', '2026-11-15', 'rule', '', '', 'Edge check: mechanical range-low longs tested at about 0R and index range-high shorts lost, so the range edge is your judgment. Log every range trade by setup (range low long, mid rejection short, range high short) to prove it in the record.', '', '', '', '', '', '');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (17, 'r4', 'Week 47', '2026-11-16', '2026-11-22', '2026-11-15', 'rule', '', '', 'BTC, ETH and INJ fell together last week: count open crypto longs as one bet and cap the combined risk. Size INJ by its own stop, not by the BTC size.', '', '', '', '', '', '');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (18, 'r5', 'Week 47', '2026-11-16', '2026-11-22', '2026-11-15', 'rule', '', '', 'No new entries in the hour around retail sales (Tue 14:30), NVIDIA''s results (Tue after the close) and the FOMC minutes (Wed 20:00).', '', '', '', '', '', '');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (19, 'e1', 'Week 47', '2026-11-16', '2026-11-22', '2026-11-15', 'risk', '', '', 'Mon 16 Nov 14:30 Zurich: Empire State manufacturing', '', '', '', '', '', '');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (20, 'e2', 'Week 47', '2026-11-16', '2026-11-22', '2026-11-15', 'risk', '', '', 'Tue 17 Nov 14:30: retail sales (Oct). After the US close (about 22:20, call 23:00): NVIDIA Q3 results, the biggest AI test since the 5 Nov sell-off', '', '', '', '', '', '');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (21, 'e3', 'Week 47', '2026-11-16', '2026-11-22', '2026-11-15', 'risk', '', '', 'Wed 18 Nov 20:00: FOMC minutes', '', '', '', '', '', '');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (22, 'e4', 'Week 47', '2026-11-16', '2026-11-22', '2026-11-15', 'risk', '', '', 'Thu 19 Nov 14:30: jobless claims and Philly Fed. Fed speakers all week (Williams, Waller, Barr, Goolsbee, Cook)', '', '', '', '', '', '');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (23, 'e5', 'Week 47', '2026-11-16', '2026-11-22', '2026-11-15', 'risk', '', '', 'Action item: write down your NVIDIA-night risk stance before Tuesday.', '', '', '', '', '', '');
